Uint8List connectionMascotFallbackBytes(String assetPath) {
  return switch (assetPath) {
    'assets/illustrations/mascot-offline-sad.png' => base64Decode(
      _offlineSadPngBase64,
    ),
    'assets/illustrations/mascot-server-confused.png' => base64Decode(
      _serverConfusedPngBase64,
    ),
    _ => Uint8List(0),
  };
}

